<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DSWD MIMAROPA Kiosk</title><style>body{margin:0;font-family:Arial;background:#f3f6fb;color:#111827;height:100vh;overflow:hidden}.wrap{height:100vh;padding:14px;display:flex}.card{background:#fff;border-radius:20px;padding:14px;box-shadow:0 12px 35px #0002;width:100%;display:flex;flex-direction:column;gap:10px}h1{text-align:center;color:#00008b;margin:0;font-size:25px;letter-spacing:3px}.note{text-align:center;color:#64748b;margin:0;font-size:12px}.tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;flex:1;min-height:0}.assist{border:0;border-radius:14px;background:#003f9e;color:white;box-shadow:0 6px 0 #002964,0 14px 24px #0003;font-weight:1000;font-size:30px;letter-spacing:5px;text-align:center;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;text-transform:uppercase;line-height:1.05}.assist .ico{font-size:52px;line-height:1}.assist:hover{filter:brightness(1.08);transform:translateY(-2px)}.assist:disabled{opacity:.55;cursor:not-allowed;transform:none}.cash{grid-column:2}.status{text-align:center;font-weight:900;min-height:22px;color:#0f766e;font-size:13px}.err{color:#dc2626}.modal{position:fixed;inset:0;background:#0008;display:none;align-items:center;justify-content:center;padding:20px;z-index:10}.pop{background:white;border-radius:24px;padding:26px;max-width:520px;width:96%;text-align:center;box-shadow:0 24px 80px #0008}.pop h2{margin:0;color:#166534}.queue{font-size:72px;font-weight:1000;color:#00008b;margin:8px 0}.btn{border:0;border-radius:999px;padding:13px 22px;font-weight:900;cursor:pointer;margin:5px}.print{background:#16a34a;color:white}.again{background:#0b2e83;color:white}.stubwrap{display:none}.stub{width:80mm;max-width:80mm;margin:0 auto;padding:8mm 6mm;background:#fff}.stub h2{text-align:center;margin:0 0 6px}.row{display:flex;justify-content:space-between;border-bottom:1px dotted #aaa;font-size:12px;padding:5px 0;gap:10px}.row b{text-align:right}@media(max-width:900px){body{overflow:auto;height:auto}.wrap{height:auto}.tiles{grid-template-columns:1fr 1fr}.assist{min-height:150px;font-size:22px}.cash{grid-column:auto}}@media(max-width:620px){.tiles{grid-template-columns:1fr}.assist{font-size:19px}.assist .ico{font-size:36px}}@media print{.wrap,.modal{display:none!important}.stubwrap{display:block}@page{size:80mm auto;margin:0}}</style></head><body><div class="wrap"><div class="card"><h1>DSWD MIMAROPA REGISTRATION KIOSK</h1><p class="note">Tap the assistance type to get a queue number.</p><div id="status" class="status"></div><div class="tiles"><button class="assist" onclick="generateQueue('Medical Assistance')"><span class="ico">✚</span>Medical<br>Assistance</button><button class="assist" onclick="generateQueue('Funeral Assistance')"><span class="ico">▰</span>Funeral<br>Assistance</button><button class="assist" onclick="generateQueue('Educational Assistance')"><span class="ico">▱</span>Educational<br>Assistance</button><button class="assist" onclick="generateQueue('Transportation Assistance')"><span class="ico">▣</span>Transportation<br>Assistance</button><button class="assist" onclick="generateQueue('Material Assistance')"><span class="ico">□</span>Material<br>Assistance</button><button class="assist" onclick="generateQueue('Food Assistance')"><span class="ico">◫</span>Food<br>Assistance</button><button class="assist cash" onclick="generateQueue('Cash Relief Assistance')"><span class="ico">₱</span>Cash Relief<br>Assistance</button></div></div></div><div id="modal" class="modal"><div class="pop"><h2>Queue Generated</h2><div id="queueNo" class="queue">-</div><p id="summary"></p><button class="btn print" onclick="printStub()">Print Stub</button><button class="btn again" onclick="resetScreen()">New Queue</button></div></div><div class="stubwrap"><div class="stub"><h2>DSWD QUEUE STUB</h2><div class="row"><span>Queue Number</span><b id="stubQueue">-</b></div><div class="row"><span>Code</span><b id="stubCode">-</b></div><div class="row"><span>Assistance</span><b id="stubProgram">-</b></div><div class="row"><span>Region</span><b>MIMAROPA</b></div><div class="row"><span>Date</span><b id="stubDate">-</b></div></div></div><script>let lastQueue=null;function msg(x,b=false){status.className='status'+(b?' err':'');status.textContent=x}function lock(x){document.querySelectorAll('.assist').forEach(b=>b.disabled=x)}async function generateQueue(program){msg('Generating queue...');lock(true);try{let body={program_type:program,first_name:'KIOSK',last_name:'CLIENT',contact_number:'09000000000',province:'Oriental Mindoro',city_municipality:'Kiosk',barangay:'Kiosk',street_address:'Kiosk'};let r=await fetch('../api/kiosk_generate_queue.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!d.success)throw Error(d.message||'Unable to generate queue');lastQueue=d;queueNo.textContent=d.queue_number;summary.textContent=d.program_type+' - MIMAROPA';setStub(d);modal.style.display='flex';msg('Queue number ready.')}catch(x){msg(x.message,true)}finally{lock(false)}}function setStub(d){stubQueue.textContent=d.queue_number||'-';stubCode.textContent=d.beneficiary_code||'-';stubProgram.textContent=d.program_type||'-';stubDate.textContent=d.date_time||new Date().toLocaleString()}function printStub(){if(lastQueue)setStub(lastQueue);setTimeout(()=>print(),80)}function resetScreen(){lastQueue=null;modal.style.display='none';msg('')}</script></body></html>